/// <summary>
/// Post load.
/// </summary>
public void postLoad()
{
    next postLoad();

    if (this.METInventDimId)
    {
        InventDim inventDim = InventDim::findInLegalEntity(this.METInventDimId, this.DataAreaId);

        if (inventDim)
        {
            this.Configuration = inventDim.configId;
            this.Size = inventDim.InventSizeId;
            this.Color = inventDim.InventColorId;
            this.Style = inventDim.InventStyleId;
            this.Site = inventDim.InventSiteId;
            this.Warehouse = inventDim.InventLocationId;
            this.Location = inventDim.wMSLocationId;
            this.InventoryStatus = inventDim.InventStatusId;
            this.LicensePlate = inventDim.LicensePlateId;
            this.BatchNumber = inventDim.inventBatchId;
            this.SerialNumber = inventDim.inventSerialId;
            this.Owner = inventDim.InventOwnerId_RU;
        }
    }
}
